// The editor's image upload: one file to Carrel's per-project media endpoint, which hands it to the site
// through the site API. Never rejects with anything but an Error that says why, so the editor shows it.

export type EditorMedia = {
  /** Carrel's media endpoint for this project: GET lists for the picker, POST uploads. */
  endpoint: string;
  /** The types the site accepts, for the file chooser's `accept`. A hint, not a control: the site checks. */
  accept: string;
  /** The site's own Markdown for an image with its alt text. */
  figure: (url: string, alt: string) => string;
};

export type Uploaded = {
  /** What the Markdown carries: the site's own address for the file. */
  url: string;
  /** Where Carrel's page loads it from, since Carrel is a different host. */
  src: string;
};

export async function uploadImage(endpoint: string, file: File): Promise<Uploaded> {
  let response: Response;
  try {
    const form = new FormData();
    form.set("file", file);
    response = await fetch(endpoint, { method: "POST", body: form });
  } catch (error) {
    throw new Error(`Upload failed: ${error instanceof Error ? error.message : String(error)}`);
  }
  const body = (await response.json().catch(() => ({}))) as { url?: string; src?: string; error?: string };
  if (!response.ok || !body.url) throw new Error(body.error ?? `Upload failed (${response.status}).`);
  return { url: body.url, src: body.src ?? body.url };
}

app/lib/frontmatter.ts.source:
// A post's source is YAML frontmatter and a Markdown body. The editor shows the frontmatter as
// fields and the body as the text, and joins them back into the one source the site stores.
//
// The join is lossless: the source is cut into the text before the body and the body, the
// frontmatter into top-level blocks (a key line and the lines that belong to it), and only a block
// whose field was changed is written again. Every other block, comment and unknown key comes back
// byte for byte. Shared by the server and the browser.

export type Split = { front: string | null; body: string; open: string; close: string };

const FENCE = /^(---[ \t]*\r?\n)([\s\S]*?)(\r?\n---[ \t]*(?:\r?\n(?:[ \t]*\r?\n)*|$))/;

/** Cuts a source into its frontmatter text, its body and the fences between, so `open + front + close + body` is the source. Blank lines after the closing fence go with the fence, so the body starts at its first line of text. */
export function splitSource(source: string): Split {
  const m = FENCE.exec(source);
  if (!m) return { front: null, body: source, open: "", close: "" };
  return { front: m[2]!, body: source.slice(m[0].length), open: m[1]!, close: m[3]! };
}

export function joinSource(s: Split): string {
  return s.front === null ? s.body : `${s.open}${s.front}${s.close}${s.body}`;
}

type Block = { key: string | null; lines: string[] };

const KEY = /^([A-Za-z_][\w-]*):(.*)$/;

function blocks(front: string): Block[] {
  const out: Block[] = [];
  for (const line of front.split("\n")) {
    const m = KEY.exec(line);
    if (m) out.push({ key: m[1]!, lines: [line] });
    else if (out.length > 0) out[out.length - 1]!.lines.push(line);
    else out.push({ key: null, lines: [line] });
  }
  return out;
}

function unquote(raw: string): string {
  const v = raw.trim();
  if (v.startsWith('"') && v.endsWith('"') && v.length >= 2) {
    try {
      return JSON.parse(v) as string;
    } catch {
      return v.slice(1, -1);
    }
  }
  if (v.startsWith("'") && v.endsWith("'") && v.length >= 2) return v.slice(1, -1).replace(/''/g, "'");
  return v;
}

function listOf(block: Block): string[] {
  const first = KEY.exec(block.lines[0]!)![2]!.trim();
  if (first.startsWith("[") && first.endsWith("]")) {
    return first
      .slice(1, -1)
      .split(",")
      .map((t) => unquote(t))
      .filter(Boolean);
  }
  return block.lines
    .slice(1)
    .map((l) => /^\s*-\s+(.*)$/.exec(l)?.[1])
    .filter((v): v is string => v !== undefined)
    .map(unquote);
}

/**
 * The fields the editor shows. A list field is a list of strings, a flag is one fixed word or nothing,
 * the rest are one line of text. `on` says which items show it: a post, a legal page, or both.
 */
export const FIELDS = [
  { key: "title", label: "Title", kind: "line", on: "all" },
  { key: "description", label: "Description", kind: "text", on: "all" },
  { key: "date", label: "Date", kind: "line", on: "post" },
  { key: "tags", label: "Tags", kind: "tags", on: "post" },
  { key: "assumed_audience", label: "Audience", kind: "text", on: "post" },
  { key: "key_takeaways", label: "Key takeaways", kind: "lines", on: "post" },
  { key: "site_name", label: "Site name", kind: "line", on: "legal" },
  { key: "operator_name", label: "Operator", kind: "line", on: "legal" },
  { key: "contact", label: "Contact", kind: "line", on: "legal" },
  { key: "jurisdiction", label: "Jurisdiction", kind: "line", on: "legal" },
  { key: "data_held", label: "Data this site holds", kind: "tags", on: "legal" },
  { key: "last_updated", label: "Last updated", kind: "line", on: "legal" },
  { key: "banner", label: "Draft banner", kind: "flag", on: "legal" },
] as const;
export type FieldKey = (typeof FIELDS)[number]["key"];
export type FieldValues = Record<FieldKey, string>;

/** The one word the banner field holds. */
export const BANNER_WORD = "Draft";

/** What each field holds now: tags as "a, b", takeaways one per line. */
export function readFields(front: string | null): FieldValues {
  const values = Object.fromEntries(FIELDS.map((f) => [f.key, ""])) as FieldValues;
  if (front === null) return values;
  for (const block of blocks(front)) {
    const field = FIELDS.find((f) => f.key === block.key);
    if (!field) continue;
    if (field.kind === "tags") values[field.key] = listOf(block).join(", ");
    else if (field.kind === "flag") values[field.key] = unquote(KEY.exec(block.lines[0]!)![2]!) === BANNER_WORD ? BANNER_WORD : "";
    else if (field.kind === "lines") values[field.key] = listOf(block).join("\n");
    else values[field.key] = unquote(KEY.exec(block.lines[0]!)![2]!);
  }
  return values;
}

function writeBlock(key: FieldKey, kind: (typeof FIELDS)[number]["kind"], value: string): string[] {
  if (kind === "tags") {
    const tags = value.split(",").map((t) => t.trim()).filter(Boolean);
    return [`${key}: [${tags.join(", ")}]`];
  }
  if (kind === "lines") {
    const items = value.split("\n").map((t) => t.trim()).filter(Boolean);
    return [`${key}:`, ...items.map((t) => `  - ${JSON.stringify(t)}`)];
  }
  if (kind === "flag") return [`${key}: ${JSON.stringify(BANNER_WORD)}`];
  if (key === "date") return [`date: ${value.trim()}`];
  return [`${key}: ${JSON.stringify(value.replace(/\s*\n\s*/g, " ").trim())}`];
}

/**
 * The frontmatter with one field set. A block whose field already holds that value is left as it
 * was; an emptied field is removed; a field the frontmatter lacks is added at the end.
 */
export function setField(front: string, key: FieldKey, value: string): string {
  const field = FIELDS.find((f) => f.key === key)!;
  if (readFields(front)[key] === value) return front;
  const all = blocks(front);
  const at = all.findIndex((b) => b.key === key);
  const fresh = value.trim() === "" ? [] : writeBlock(key, field.kind, value);
  if (at >= 0) {
    if (fresh.length > 0) all[at] = { key, lines: fresh };
    else all.splice(at, 1);
  } else if (fresh.length > 0) {
    all.push({ key, lines: fresh });
  }
  return all.flatMap((b) => b.lines).join("\n");
}

/** The tags the frontmatter holds now, in order. */
export function tagsOf(front: string | null): string[] {
  const tags = readFields(front).tags;
  return tags === "" ? [] : tags.split(",").map((t) => t.trim()).filter(Boolean);
}

/**
 * The frontmatter with its tags set to exactly this list, and nothing else touched. Unlike
 * setField, an empty list is written as `tags: []`, not removed: a post that lost its last tag keeps
 * the key the site's own new-post template starts with. A list in block form comes back in flow form.
 */
export function setTags(front: string, tags: string[]): string {
  const all = blocks(front);
  const fresh = { key: "tags", lines: [`tags: [${tags.join(", ")}]`] };
  const at = all.findIndex((b) => b.key === "tags");
  if (at >= 0) {
    if (all[at]!.lines.length === 1 && all[at]!.lines[0] === fresh.lines[0]) return front;
    all[at] = fresh;
  } else {
    all.push(fresh);
  }
  return all.flatMap((b) => b.lines).join("\n");
}

/** The frontmatter with a top-level key set to a raw value (`draft: true`), added at the end when absent. Every other block is returned as it was. */
export function setRawKey(front: string, key: string, raw: string): string {
  const all = blocks(front);
  const line = `${key}: ${raw}`;
  const at = all.findIndex((b) => b.key === key);
  if (at >= 0) {
    if (all[at]!.lines.length === 1 && all[at]!.lines[0] === line) return front;
    all[at] = { key, lines: [line] };
  } else {
    all.push({ key, lines: [line] });
  }
  return all.flatMap((b) => b.lines).join("\n");
}

app/lib/mcp/door.ts.source:
// The AI door: everything on carrel-mcp.dustinedwards.info (design decision 7, corrected 2026-09-27).
//
// That hostname is exempt from Carrel's Worker-level Access (a hostname Bypass app, setup in the PR),
// because an MCP client must reach the OAuth endpoints before anyone has signed in. So nothing here
// trusts Access's own header. Instead this door is an OAuth 2.1 authorization server of its own
// (@cloudflare/workers-oauth-provider): CIMD only, no registration endpoint, and the person signs in
// upstream through Cloudflare Access for SaaS (access-login.ts). The verified email must belong to an
// active person in Carrel, checked when the grant is made and again on every request.
//
// Every request through this door is an AI session, told apart by the hostname it arrived on, never
// by email. The pages are never served here, and this door is never served on the browser's host.
//
// Routes on this host, outermost first:
//   /mcp                          a named agent key (agent-keys.server.ts) goes straight to agentHandler;
//                                 anything else: the provider checks the bearer token, then apiHandler
//                                 finds the person and hands the request to server.ts
//   /authorize  /callback         the consent page and the Access sign-in, below
//   /token, /.well-known/*        served by the provider
//   /health                       liveness
//   anything else                 404

import OAuthProvider, { AuthorizationError, CimdFetchError, type AuthRequest, type ClientInfo, type OAuthHelpers } from "@cloudflare/workers-oauth-provider";

import { agentClient, agentPrincipal } from "~/lib/agent-keys.server";
import { findAgentViewer, findViewer } from "~/lib/people.server";

import { accessSaas, authorizationUrl, finishSignIn, newSignIn } from "./access-login";
import { carrelOrigin, handleMcp, MCP_ROUTE } from "./server";

/** The one scope a grant carries. What a session may do comes from the person's role, not the scope. */
export const SCOPE = "carrel";

/** What a grant stores, encrypted, and hands to every request made with its tokens. */
export type DoorProps = { personId: number; email: string; client: string; clientId: string };

type DoorEnv = Env & { OAUTH_PROVIDER: OAuthHelpers };

/**
 * The AI door's origin. Read loosely, like CARREL_ORIGIN, because a wrangler.jsonc from before this
 * change has no CARREL_MCP_ORIGIN and its generated types would not either.
 */
export function mcpOrigin(env: Env): string {
  const configured = (env as { CARREL_MCP_ORIGIN?: string }).CARREL_MCP_ORIGIN?.trim();
  return (configured || "https://carrel-mcp.dustinedwards.info").replace(/\/+$/, "");
}

/** Whether a request arrived on the AI door's hostname. The only thing that decides the door. */
export function isMcpHost(request: Request, env: Env): boolean {
  return new URL(request.url).host.toLowerCase() === new URL(mcpOrigin(env)).host.toLowerCase();
}

const PRIVATE_HEADERS: Record<string, string> = {
  "Cache-Control": "no-store",
  "X-Content-Type-Options": "nosniff",
  "Referrer-Policy": "no-referrer",
  "X-Robots-Tag": "noindex, nofollow",
};

function text(body: string, status: number, headers?: Headers): Response {
  const out = new Headers(headers);
  out.set("Content-Type", "text/plain; charset=utf-8");
  for (const [name, value] of Object.entries(PRIVATE_HEADERS)) out.set(name, value);
  return new Response(body, { status, headers: out });
}

function redirect(location: string, headers?: Headers): Response {
  const out = new Headers(headers);
  out.set("Location", location);
  out.set("Cache-Control", "no-store");
  return new Response(null, { status: 302, headers: out });
}

/** The OAuth error answer to the client, once its redirect URI is known good. */
function redirectError(request: AuthRequest, description: string, headers?: Headers): Response {
  const url = new URL(request.redirectUri);
  url.searchParams.set("error", "access_denied");
  url.searchParams.set("error_description", description);
  url.searchParams.set("state", request.state);
  if (request.issuer) url.searchParams.set("iss", request.issuer);
  return redirect(url.href, headers);
}

const escape = (value: string) => value.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);

/** The name a client is credited by: its CIMD client_name, or else the host that publishes it. */
function clientLabel(client: ClientInfo | null, clientId: string): string {
  const name = client?.clientName?.trim();
  if (name) return name.slice(0, 100);
  try {
    return new URL(clientId).hostname;
  } catch {
    return "an unnamed AI client";
  }
}

/**
 * The consent page. Consent has to be an act, so it is a real form. Everything from the client is
 * escaped: a CIMD document's name is chosen by whoever serves it.
 */
function consentPage(client: ClientInfo | null, request: AuthRequest, handle: string): string {
  const name = escape(clientLabel(client, request.clientId));
  const redirectHost = new URL(request.redirectUri).hostname;
  const local = /^(localhost|127(\.\d{1,3}){3}|\[::1\])$/.test(redirectHost);
  const publisher = request.clientId.startsWith("https://") ? `Published by <strong>${escape(new URL(request.clientId).hostname)}</strong>.` : "";
  return `<!doctype html>
<html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex,nofollow">
<title>Allow ${name} to use Carrel?</title>
<style>
  :root { color-scheme: light dark; }
  body { font: 17px/1.6 Georgia, "Iowan Old Style", serif; max-width: 34rem; margin: 4rem auto; padding: 0 1.25rem; }
  h1 { font-size: 1.4rem; line-height: 1.3; }
  .fine { font-size: .9rem; opacity: .8; }
  button { font: inherit; padding: .55rem 1.1rem; border-radius: .35rem; cursor: pointer; margin-right: .5rem; }
</style>
</head><body>
<h1>Allow ${name} to use Carrel as you?</h1>
<p>${publisher} Its access will be sent to <strong>${escape(redirectHost)}</strong>.</p>
${local ? "<p><strong>This sends access to an app on your computer.</strong> Continue only if you just started signing in from it.</p>" : ""}
<p>It can do what your role in Carrel allows, and nothing more: read, save AI drafts beside yours, and flag problems. Publishing is for Dustin's own sessions only, and never while a flag is open.</p>
<p class="fine">Next you sign in with Cloudflare Access. Only people Carrel already knows are let in.</p>
<form method="post">
  <input type="hidden" name="handle" value="${escape(handle)}">
  <button name="decision" value="approve">Continue to sign in</button>
  <button name="decision" value="deny">Deny</button>
</form>
</body></html>`;
}

async function authorizeGet(request: Request, env: DoorEnv): Promise<Response> {
  if (!accessSaas(env)) return text("Carrel's AI door is not configured: ACCESS_SAAS_CLIENT_ID or ACCESS_SAAS_CLIENT_SECRET is unset. Not configured means not open.", 503);
  const oauth = env.OAUTH_PROVIDER;
  const authRequest = await oauth.parseAuthRequest(request);
  const client = await oauth.lookupClient(authRequest.clientId);
  if (!client) return text("Unknown OAuth client.", 400);
  const consent = await oauth.beginConsent(authRequest);
  consent.headers.set("Content-Type", "text/html; charset=utf-8");
  // no-transform keeps Cloudflare from injecting its Web Analytics beacon into this page.
  consent.headers.set("Cache-Control", "no-store, no-transform");
  return new Response(consentPage(client, authRequest, consent.handle), { headers: consent.headers });
}

async function authorizePost(request: Request, env: DoorEnv): Promise<Response> {
  const saas = accessSaas(env);
  if (!saas) return text("Carrel's AI door is not configured. Not configured means not open.", 503);
  const oauth = env.OAUTH_PROVIDER;
  const form = await request.formData();
  const handle = String(form.get("handle") ?? "");
  if (form.get("decision") !== "approve") {
    const denied = await oauth.denyConsent(request, handle);
    return new Response(null, { status: 302, headers: denied.headers });
  }
  const approved = await oauth.approveConsent(request, handle, { scope: [SCOPE] });
  // Only now, after consent, does the sign-in start. The verifier and nonce stay server-side.
  const signIn = newSignIn();
  const { state, headers } = await oauth.beginUpstream(approved.request, { data: signIn, headers: approved.headers });
  return redirect(await authorizationUrl(saas, { redirectUri: `${mcpOrigin(env)}/callback`, state, ...signIn }), headers);
}

async function callback(request: Request, env: DoorEnv): Promise<Response> {
  const saas = accessSaas(env);
  if (!saas) return text("Carrel's AI door is not configured. Not configured means not open.", 503);
  const oauth = env.OAUTH_PROVIDER;
  const { request: original, data, headers } = await oauth.finishUpstream<{ verifier: string; nonce: string }>(request);
  const params = new URL(request.url).searchParams;
  const code = params.get("code");
  if (params.get("error") || !code) return redirectError(original, "Sign-in with Cloudflare Access did not complete.", headers);

  const signedIn = await finishSignIn(saas, { code, redirectUri: `${mcpOrigin(env)}/callback`, verifier: data.verifier, nonce: data.nonce });
  if (!signedIn.ok) {
    console.warn(JSON.stringify({ door: "sign-in-refused", reason: signedIn.reason }));
    return redirectError(original, "Carrel could not verify the sign-in.", headers);
  }
  const viewer = await findViewer(env.DB, signedIn.email);
  if (!viewer) {
    // Access let them in, but Carrel does not know them: no row, no access (design section 3).
    console.warn(JSON.stringify({ door: "refused", reason: "unknown-person" }));
    return redirectError(original, "This person is not in Carrel.", headers);
  }

  const client = clientLabel(await oauth.lookupClient(original.clientId).catch(() => null), original.clientId);
  const props: DoorProps = { personId: viewer.id, email: viewer.email, client, clientId: original.clientId };
  const { redirectTo } = await oauth.completeAuthorization({
    request: original,
    userId: String(viewer.id),
    metadata: { client },
    scope: original.scope,
    props,
  });
  headers.set("Location", redirectTo);
  headers.set("Cache-Control", "no-store");
  return new Response(null, { status: 302, headers });
}

/** Everything on this host the provider does not own. */
const loginHandler = {
  async fetch(request: Request, env: DoorEnv): Promise<Response> {
    const { pathname } = new URL(request.url);
    try {
      if (pathname === "/health") return text("ok", 200);
      if (pathname === "/authorize" && request.method === "GET") return await authorizeGet(request, env);
      if (pathname === "/authorize" && request.method === "POST") return await authorizePost(request, env);
      if (pathname === "/callback" && request.method === "GET") return await callback(request, env);
      return text("Not found.", 404);
    } catch (error) {
      // Per the provider's consent-page guide: redirect only to a validated client, render the rest.
      if (error instanceof AuthorizationError && error.redirectUri) {
        const url = new URL(error.redirectUri);
        url.searchParams.set("error", error.code);
        url.searchParams.set("error_description", error.description);
        if (error.state) url.searchParams.set("state", error.state);
        if (error.issuer) url.searchParams.set("iss", error.issuer);
        return redirect(url.href);
      }
      if (error instanceof AuthorizationError) return text(`${error.description} Start the sign-in again from your MCP client.`, 400);
      if (error instanceof CimdFetchError) return text("This app could not be verified: its client metadata document could not be fetched.", 400);
      throw error;
    }
  },
};

/**
 * The authenticated MCP surface. The provider has checked the token by the time this runs. The
 * person is looked up again on every request: a grant lives for weeks, and a person disabled in
 * Carrel must lose the door at once, not when the grant expires.
 */
const apiHandler = {
  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const props = (ctx as ExecutionContext & { props?: Partial<DoorProps> }).props;
    const viewer = props?.email ? await findViewer(env.DB, props.email) : null;
    if (!viewer || viewer.id !== props?.personId) {
      console.warn(JSON.stringify({ door: "refused", reason: viewer ? "person-changed" : "unknown-person" }));
      return text("Forbidden. This grant does not belong to an active person in Carrel.", 403);
    }
    const response = await handleMcp(request, env, ctx, { viewer, client: props.client || "an unnamed AI client" }, { carrelOrigin: carrelOrigin(env) });
    const out = new Response(response.body, response);
    for (const [name, value] of Object.entries(PRIVATE_HEADERS)) out.headers.set(name, value);
    return out;
  },
};

/**
 * The named-agent surface. A key (agent-keys.server.ts) names an agent, and the agent is the person
 * row "agent:<name>" in Carrel's People table, found again on every request: disabling that row
 * revokes the agent at once, and its role on each project is whatever People says, never the key's.
 * A key with no active row is refused here and never falls through to anything. Writes are credited
 * to "agent:<name>", the same text as the person, never to Dustin.
 */
async function agentHandler(request: Request, env: Env, ctx: ExecutionContext, name: string): Promise<Response> {
  const viewer = await findAgentViewer(env.DB, name);
  if (!viewer) {
    console.warn(JSON.stringify({ door: "refused", reason: "agent-not-in-carrel", agent: name }));
    return text("Forbidden. This agent key does not belong to an active agent in Carrel.", 403);
  }
  console.log(JSON.stringify({ door: "agent-key-accepted", agent: name }));
  const response = await handleMcp(request, env, ctx, { viewer, client: agentClient(name) }, { carrelOrigin: carrelOrigin(env) });
  const out = new Response(response.body, response);
  for (const [header, value] of Object.entries(PRIVATE_HEADERS)) out.headers.set(header, value);
  return out;
}

const providers = new Map<string, OAuthProvider<Env>>();

/** One provider per origin: its resource URI is fixed at construction. */
function providerFor(env: Env): OAuthProvider<Env> {
  const origin = mcpOrigin(env);
  let provider = providers.get(origin);
  if (!provider) {
    provider = new OAuthProvider<Env>({
      apiRoute: MCP_ROUTE,
      apiHandler,
      defaultHandler: loginHandler as unknown as ExportedHandler<Env>,
      authorizeEndpoint: "/authorize",
      tokenEndpoint: "/token",
      scopesSupported: [SCOPE],
      resourceMetadata: {
        resource: `${origin}${MCP_ROUTE}`,
        authorization_servers: [origin],
        scopes_supported: [SCOPE],
        resource_name: "Carrel",
      },
      // CIMD ONLY. claude.ai and Claude Code send their client_id as a metadata URL and never call a
      // registration endpoint (measured in dustinedwards-mcp, 2026-07-30), and MCP 2026-07-28
      // deprecates dynamic registration. There is deliberately no clientRegistrationEndpoint: no
      // client can mint itself an identity here. Needs global_fetch_strictly_public in wrangler.jsonc.
      clientIdMetadataDocumentEnabled: true,
    });
    providers.set(origin, provider);
  }
  return provider;
}

/** Serves one request that arrived on the AI door's hostname. */
export async function aiDoor(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
  const { pathname } = new URL(request.url);
  if (pathname === MCP_ROUTE || pathname.startsWith(`${MCP_ROUTE}/`)) {
    // Tried, never required: no match (no secret, a bad header, an OAuth token) is the OAuth path, unchanged.
    const agent = await agentPrincipal(env, request.headers.get("Authorization"));
    if (agent) return agentHandler(request, env, ctx, agent);
  }
  return providerFor(env).fetch(request, env, ctx);
}

app/lib/social/queue.server.ts.source:
// The social queue (design decision 5). A piece going live is the only thing a post can announce.
// For each account that announces that project, the post comes from, in order:
//
//   1. a draft stored ahead by the session that finished the piece (draftSocialPost);
//   2. else a Claude Code routine Carrel fires, batching every waiting item into one run (the
//      routine stores its drafts the same way), with a nightly sweep;
//   3. else, when the routine fails or its daily cap is reached, or it drafted nothing in time, a
//      template post, which the health check reports to Dustin.
//
// Every post is linted; a finding holds it for Dustin. Then each account's switch decides: approval
// (Dustin approves each post) or auto (it goes when the caps allow). Nothing here calls an AI. The
// loop over accounts, the daily cap, the gap between posts and the record of every post are carried
// over from legacy Recova's social-poster cron.

import { and, asc, desc, eq, gte, inArray, isNotNull, isNull, lte } from "drizzle-orm";
import { drizzle } from "drizzle-orm/d1";

import { socialAccounts, socialEvents, socialPosts, socialRoutineRuns } from "~/db/schema";
import type { Viewer } from "~/lib/people.server";

import { lintPost } from "./lint";
import { credentialsFor, postOriginal, xCostMills } from "./platforms.server";
import { fireRoutine, routineConfig, routinePrompt } from "./routine.server";

type Fetch = typeof fetch;

/** How long published items gather before one routine run takes them all. */
export const BATCH_DELAY_MS = 30 * 60_000;
/** How long the routine has to store its drafts before the template is used. */
export const ROUTINE_WAIT_MS = 3 * 60 * 60_000;
/** Routine runs a day: one to three, under the subscription's routine cap (design decision 5). */
export const ROUTINE_DAILY_CAP = 3;
/** The nightly sweep's hour, UTC (3 a.m. Central in daylight time). */
export const NIGHTLY_HOUR_UTC = 8;

const DEFAULT_TEMPLATE = "New: {title}. {summary} {link}";

function requireOwner(viewer: Viewer) {
  if (!viewer.isOwner) throw new Response("Not found", { status: 404 });
}

function dayStart(now: Date): string {
  return `${now.toISOString().slice(0, 10)}T00:00:00.000Z`;
}

function monthStart(now: Date): string {
  return `${now.toISOString().slice(0, 7)}-01T00:00:00.000Z`;
}

// ---------- accounts and switches

export type AccountInput = { key: string; name: string; platform: "bluesky" | "x"; kind: "personal" | "brand"; handle: string; projectId: number | null };

export async function createAccount(db: D1Database, viewer: Viewer, input: AccountInput) {
  requireOwner(viewer);
  if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(input.key)) return { ok: false as const, error: "The key is lower-case letters, digits and hyphens, such as germomics-bluesky." };
  if (!input.name.trim() || !input.handle.trim()) return { ok: false as const, error: "Give the account a name and its handle." };
  try {
    // Every account starts off, in approval mode.
    await drizzle(db).insert(socialAccounts).values({ ...input, name: input.name.trim(), handle: input.handle.trim().replace(/^@/, ""), enabled: false, mode: "approval" });
  } catch {
    return { ok: false as const, error: `An account with the key ${input.key} already exists.` };
  }
  return { ok: true as const };
}

export async function setSwitches(db: D1Database, viewer: Viewer, id: number, input: { enabled?: boolean; mode?: "approval" | "auto"; dailyCap?: number; monthlyBudgetMills?: number; template?: string; voiceGuide?: string }) {
  requireOwner(viewer);
  const d = drizzle(db);
  const account = await d.select().from(socialAccounts).where(eq(socialAccounts.id, id)).get();
  if (!account) throw new Response("Not found", { status: 404 });
  // The personal account is approved post by post, always.
  if (input.mode === "auto" && account.kind === "personal") return { ok: false as const, error: "The personal account is always approval: every post is Dustin's call." };
  const set: Partial<typeof socialAccounts.$inferInsert> = {};
  if (input.enabled !== undefined) set.enabled = input.enabled;
  if (input.mode) set.mode = input.mode;
  if (input.dailyCap !== undefined) set.dailyCap = Math.max(0, Math.min(20, Math.floor(input.dailyCap)));
  if (input.monthlyBudgetMills !== undefined) set.monthlyBudgetMills = Math.max(0, Math.floor(input.monthlyBudgetMills));
  if (input.template !== undefined) set.template = input.template.slice(0, 500);
  if (input.voiceGuide !== undefined) set.voiceGuide = input.voiceGuide.slice(0, 4000);
  if (Object.keys(set).length) await d.update(socialAccounts).set(set).where(eq(socialAccounts.id, id));
  return { ok: true as const };
}

// ---------- events and drafts

/** The description line in a post's frontmatter: Dustin's one-line summary, for templates and the routine. */
export function summaryFrom(source: string): string {
  const fm = /^---\n([\s\S]*?)\n---/.exec(source.replace(/\r\n/g, "\n"))?.[1] ?? "";
  return /^description:\s*"?(.*?)"?\s*$/m.exec(fm)?.[1]?.trim() ?? "";
}

/**
 * A piece went live: every account announcing its project gets an event, which becomes sendable now.
 * An account that is off when the piece goes live closes its event, so turning it on later does
 * not post a backlog.
 */
export async function recordPublication(db: D1Database, projectId: number, item: { id: string; title: string; url: string; summary: string }, now = new Date()) {
  const d = drizzle(db);
  const accounts = await d.select().from(socialAccounts).where(eq(socialAccounts.projectId, projectId)).all();
  for (const account of accounts) {
    const values = { title: item.title, url: item.url, summary: item.summary, publishedAt: now.toISOString() };
    const existing = await d
      .select()
      .from(socialEvents)
      .where(and(eq(socialEvents.accountId, account.id), eq(socialEvents.projectId, projectId), eq(socialEvents.itemId, item.id)))
      .get();
    if (existing?.publishedAt) continue; // Announced once, not on every re-publish.
    const state = account.enabled ? (existing?.state ?? "waiting") : "closed";
    if (existing) await d.update(socialEvents).set({ ...values, state }).where(eq(socialEvents.id, existing.id));
    else await d.insert(socialEvents).values({ accountId: account.id, projectId, itemId: item.id, ...values, state });
  }
}

/**
 * Stores a drafted post for an account and a piece, ahead of publication or after the routine was
 * asked for it. The newest draft replaces any earlier one that has not gone out. This is what the
 * session that finishes a piece, and the routine, call through MCP.
 */
export async function draftSocialPost(db: D1Database, input: { accountKey: string; projectId: number; itemId: string; text: string; createdBy: string }) {
  const d = drizzle(db);
  const account = await d.select().from(socialAccounts).where(eq(socialAccounts.key, input.accountKey)).get();
  if (!account || account.projectId !== input.projectId) return { ok: false as const, error: `No account ${input.accountKey} announces this project.` };
  let event = await d
    .select()
    .from(socialEvents)
    .where(and(eq(socialEvents.accountId, account.id), eq(socialEvents.projectId, input.projectId), eq(socialEvents.itemId, input.itemId)))
    .get();
  if (!event) {
    [event] = await d.insert(socialEvents).values({ accountId: account.id, projectId: input.projectId, itemId: input.itemId }).returning();
  }
  if (event!.state === "templated" || event!.state === "closed") return { ok: false as const, error: "This item's post was already settled (template used, or the account was off)." };
  await d
    .update(socialPosts)
    .set({ status: "rejected", error: "Replaced by a newer draft." })
    .where(and(eq(socialPosts.eventId, event!.id), inArray(socialPosts.status, ["drafted", "held", "awaiting", "queued"])));
  const [post] = await d
    .insert(socialPosts)
    .values({ accountId: account.id, eventId: event!.id, text: input.text.trim(), source: event!.state === "routine" ? "routine" : "predrafted", status: "drafted", createdBy: input.createdBy })
    .returning({ id: socialPosts.id });
  return { ok: true as const, postId: post!.id };
}

/** The routine is told each item by its event id; this stores its draft for that event. */
export async function draftForEvent(db: D1Database, input: { eventId: number; text: string; createdBy: string }) {
  const row = await drizzle(db)
    .select({ event: socialEvents, key: socialAccounts.key })
    .from(socialEvents)
    .innerJoin(socialAccounts, eq(socialAccounts.id, socialEvents.accountId))
    .where(eq(socialEvents.id, input.eventId))
    .get();
  if (!row) return { ok: false as const, error: `No social event ${input.eventId}.` };
  return draftSocialPost(db, { accountKey: row.key, projectId: row.event.projectId, itemId: row.event.itemId, text: input.text, createdBy: input.createdBy });
}

function fillTemplate(template: string, event: { title: string; summary: string; url: string }): string {
  return (template || DEFAULT_TEMPLATE)
    .replaceAll("{title}", event.title)
    .replaceAll("{summary}", event.summary)
    .replaceAll("{link}", event.url)
    .replace(/\s+/g, " ")
    .replace(/\s+([.,])/g, "$1")
    .replace(/\.\./g, ".")
    .trim();
}

// ---------- the tick

export type TickResult = { linted: number; routineFired: number; templated: number; sent: number; waitingOnCaps: number; errors: string[] };

type Account = typeof socialAccounts.$inferSelect;

/** Lints a drafted post and routes it by the account's switch. */
async function route(db: D1Database, post: typeof socialPosts.$inferSelect, account: Account) {
  const findings = lintPost(post.text, account.platform);
  const status = findings.length ? "held" : account.mode === "auto" ? "queued" : "awaiting";
  await drizzle(db).update(socialPosts).set({ status, lint: JSON.stringify(findings) }).where(eq(socialPosts.id, post.id));
  await drizzle(db).update(socialEvents).set({ state: "covered" }).where(and(eq(socialEvents.id, post.eventId), inArray(socialEvents.state, ["waiting", "routine"])));
}

async function useTemplate(db: D1Database, event: typeof socialEvents.$inferSelect, account: Account) {
  const d = drizzle(db);
  const [post] = await d
    .insert(socialPosts)
    .values({ accountId: account.id, eventId: event.id, text: fillTemplate(account.template, event), source: "template", status: "drafted", createdBy: "template" })
    .returning();
  await d.update(socialEvents).set({ state: "templated" }).where(eq(socialEvents.id, event.id));
  await route(db, post!, account);
}

async function sendQueued(env: Env, account: Account, now: Date, fetcher: Fetch, result: TickResult) {
  const d = drizzle(env.DB);
  const queued = await d.select().from(socialPosts).where(and(eq(socialPosts.accountId, account.id), eq(socialPosts.status, "queued"))).orderBy(asc(socialPosts.id)).all();
  if (queued.length === 0) return;
  const sent = await d
    .select({ sentAt: socialPosts.sentAt, cost: socialPosts.costMills })
    .from(socialPosts)
    .where(and(eq(socialPosts.accountId, account.id), eq(socialPosts.status, "sent"), gte(socialPosts.sentAt, monthStart(now))))
    .orderBy(desc(socialPosts.sentAt))
    .all();
  let today = sent.filter((s) => s.sentAt! >= dayStart(now)).length;
  let spent = sent.reduce((n, s) => n + s.cost, 0);
  let last = sent[0]?.sentAt ? Date.parse(sent[0].sentAt) : 0;
  const creds = credentialsFor(env, account);

  for (const post of queued) {
    // Recova's caps, per account: the daily cap and the gap between posts; X's monthly budget too.
    if (today >= account.dailyCap || now.getTime() - last < account.minGapMinutes * 60_000) {
      result.waitingOnCaps++;
      return;
    }
    const cost = account.platform === "x" ? xCostMills(post.text) : 0;
    if (account.platform === "x" && spent + cost > account.monthlyBudgetMills) {
      await d.update(socialPosts).set({ error: `Held: it would pass this month's X budget ($${(account.monthlyBudgetMills / 1000).toFixed(2)}).` }).where(eq(socialPosts.id, post.id));
      result.waitingOnCaps++;
      return;
    }
    if ("missing" in creds) {
      await d.update(socialPosts).set({ error: `Waiting for credentials: ${creds.missing.join(", ")}.` }).where(eq(socialPosts.id, post.id));
      result.errors.push(`${account.key}: credentials missing`);
      return;
    }
    try {
      const id = await postOriginal(creds, post.text, fetcher, now.getTime());
      await d.update(socialPosts).set({ status: "sent", platformPostId: id, costMills: cost, sentAt: now.toISOString(), error: null }).where(eq(socialPosts.id, post.id));
      today++;
      spent += cost;
      last = now.getTime();
      result.sent++;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      await d.update(socialPosts).set({ status: "failed", error: message }).where(eq(socialPosts.id, post.id));
      result.errors.push(`${account.key}: ${message}`);
    }
  }
}

/** One pass of the queue, run by the cron. Every step is idempotent, so a missed run loses nothing. */
export async function processSocial(env: Env, deps: { fetcher?: Fetch; now?: Date } = {}): Promise<TickResult> {
  const fetcher = deps.fetcher ?? fetch;
  const now = deps.now ?? new Date();
  const d = drizzle(env.DB);
  const result: TickResult = { linted: 0, routineFired: 0, templated: 0, sent: 0, waitingOnCaps: 0, errors: [] };
  const accounts = new Map((await d.select().from(socialAccounts).where(eq(socialAccounts.enabled, true)).all()).map((a) => [a.id, a]));
  if (accounts.size === 0) return result;
  const ids = [...accounts.keys()];

  // 1. Drafts for published pieces, stored ahead or by the routine: lint, then the switch.
  const drafted = await d
    .select({ post: socialPosts })
    .from(socialPosts)
    .innerJoin(socialEvents, eq(socialEvents.id, socialPosts.eventId))
    .where(and(eq(socialPosts.status, "drafted"), isNotNull(socialEvents.publishedAt), inArray(socialPosts.accountId, ids)))
    .all();
  for (const { post } of drafted) {
    await route(env.DB, post, accounts.get(post.accountId)!);
    result.linted++;
  }

  // 3a. The routine was asked and drafted nothing in time: the template.
  const stale = await d
    .select({ event: socialEvents, requestedAt: socialRoutineRuns.requestedAt })
    .from(socialEvents)
    .innerJoin(socialRoutineRuns, eq(socialRoutineRuns.id, socialEvents.routineRunId))
    .where(and(eq(socialEvents.state, "routine"), inArray(socialEvents.accountId, ids), lte(socialRoutineRuns.requestedAt, new Date(now.getTime() - ROUTINE_WAIT_MS).toISOString())))
    .all();
  for (const { event } of stale) {
    await useTemplate(env.DB, event, accounts.get(event.accountId)!);
    result.templated++;
  }

  // 2. Published pieces with no draft: one routine run for all of them, after the batch delay, or
  // at the nightly sweep.
  const nightly = now.getUTCHours() === NIGHTLY_HOUR_UTC;
  const waiting = (
    await d
      .select()
      .from(socialEvents)
      .where(and(eq(socialEvents.state, "waiting"), isNotNull(socialEvents.publishedAt), inArray(socialEvents.accountId, ids)))
      .all()
  ).filter((e) => nightly || Date.parse(e.publishedAt!) <= now.getTime() - BATCH_DELAY_MS);
  if (waiting.length > 0) {
    const config = routineConfig(env);
    const runsToday = await d.select({ id: socialRoutineRuns.id }).from(socialRoutineRuns).where(and(eq(socialRoutineRuns.status, "fired"), gte(socialRoutineRuns.requestedAt, dayStart(now)))).all();
    let templateAll: string | null = null;
    if ("missing" in config) templateAll = config.missing;
    else if (runsToday.length >= ROUTINE_DAILY_CAP) templateAll = `the routine's daily cap of ${ROUTINE_DAILY_CAP} runs is reached`;
    else {
      const prompt = routinePrompt(
        waiting.map((e) => {
          const a = accounts.get(e.accountId)!;
          return { eventId: e.id, account: `${a.name} (${a.key})`, platform: a.platform, voiceGuide: a.voiceGuide, title: e.title, url: e.url, summary: e.summary };
        }),
      );
      const fired = await fireRoutine(config, prompt, fetcher);
      const [run] = await d
        .insert(socialRoutineRuns)
        .values({
          kind: nightly ? "nightly" : "batch",
          requestedAt: now.toISOString(),
          events: JSON.stringify(waiting.map((e) => e.id)),
          status: fired.ok ? "fired" : "failed",
          sessionUrl: fired.ok ? fired.sessionUrl : null,
          error: fired.ok ? null : fired.error,
        })
        .returning({ id: socialRoutineRuns.id });
      if (fired.ok) {
        await d.update(socialEvents).set({ state: "routine", routineRunId: run!.id }).where(inArray(socialEvents.id, waiting.map((e) => e.id)));
        result.routineFired++;
      } else if (!fired.retry) {
        templateAll = `the routine refused the run (${fired.error})`;
      } else {
        // The hourly limit or a brief outage: the next tick tries again; the items keep waiting.
        result.errors.push(`routine: ${fired.error}`);
      }
    }
    if (templateAll) {
      result.errors.push(`template used: ${templateAll}`);
      for (const event of waiting) {
        await useTemplate(env.DB, event, accounts.get(event.accountId)!);
        result.templated++;
      }
    }
  }

  // Posts cleared to go: within each account's caps.
  for (const account of accounts.values()) await sendQueued(env, account, now, fetcher, result);
  return result;
}

// ---------- Dustin's decisions

export async function decidePost(
  db: D1Database,
  viewer: Viewer,
  id: number,
  decision: { action: "approve" | "reject" | "by-hand" | "acknowledge" } | { action: "edit"; text: string },
  now = new Date(),
) {
  requireOwner(viewer);
  const d = drizzle(db);
  const row = await d.select({ post: socialPosts, account: socialAccounts }).from(socialPosts).innerJoin(socialAccounts, eq(socialAccounts.id, socialPosts.accountId)).where(eq(socialPosts.id, id)).get();
  if (!row) throw new Response("Not found", { status: 404 });
  const { post, account } = row;
  const open = ["held", "awaiting"].includes(post.status);
  switch (decision.action) {
    case "approve":
      // A held post is approved only once its text passes the lint (edit it first).
      if (post.status !== "awaiting") return { ok: false as const, error: post.status === "held" ? "Edit the post until the lint passes, then approve it." : "Only a post awaiting approval can be approved." };
      await d.update(socialPosts).set({ status: "queued", approvedBy: viewer.id }).where(eq(socialPosts.id, id));
      return { ok: true as const };
    case "reject":
      if (!open && post.status !== "queued") return { ok: false as const, error: "Only a post that has not gone out can be rejected." };
      await d.update(socialPosts).set({ status: "rejected", approvedBy: viewer.id }).where(eq(socialPosts.id, id));
      return { ok: true as const };
    case "by-hand":
      // The personal account's free path: Dustin copies the text and posts it himself.
      if (!open) return { ok: false as const, error: "Only a post that has not gone out can be posted by hand." };
      await d.update(socialPosts).set({ status: "by-hand", approvedBy: viewer.id, sentAt: now.toISOString() }).where(eq(socialPosts.id, id));
      return { ok: true as const };
    case "edit": {
      if (!open) return { ok: false as const, error: "Only a held or awaiting post can be edited." };
      const findings = lintPost(decision.text, account.platform);
      await d.update(socialPosts).set({ text: decision.text.trim(), lint: JSON.stringify(findings), status: findings.length ? "held" : "awaiting" }).where(eq(socialPosts.id, id));
      return { ok: true as const, findings };
    }
    case "acknowledge":
      if (post.source !== "template") return { ok: false as const, error: "Only a template post has an alert to acknowledge." };
      await d.update(socialPosts).set({ acknowledgedAt: now.toISOString() }).where(eq(socialPosts.id, id));
      return { ok: true as const };
  }
}

// ---------- reading

export async function socialOverview(db: D1Database, viewer: Viewer) {
  requireOwner(viewer);
  const d = drizzle(db);
  const [accounts, posts, runs] = await Promise.all([
    d.select().from(socialAccounts).orderBy(asc(socialAccounts.key)).all(),
    d
      .select({ post: socialPosts, title: socialEvents.title, url: socialEvents.url, accountKey: socialAccounts.key, platform: socialAccounts.platform, kind: socialAccounts.kind })
      .from(socialPosts)
      .innerJoin(socialEvents, eq(socialEvents.id, socialPosts.eventId))
      .innerJoin(socialAccounts, eq(socialAccounts.id, socialPosts.accountId))
      .orderBy(desc(socialPosts.id))
      .limit(100)
      .all(),
    d.select().from(socialRoutineRuns).orderBy(desc(socialRoutineRuns.id)).limit(10).all(),
  ]);
  return { accounts, posts, runs };
}

/** Template posts that went out and Dustin has not yet marked seen: the health check's alert. */
export async function unseenTemplates(db: D1Database) {
  return drizzle(db)
    .select({ id: socialPosts.id, accountKey: socialAccounts.key, text: socialPosts.text })
    .from(socialPosts)
    .innerJoin(socialAccounts, eq(socialAccounts.id, socialPosts.accountId))
    .where(and(eq(socialPosts.source, "template"), eq(socialPosts.status, "sent"), isNull(socialPosts.acknowledgedAt)))
    .all();
}

app/routes/book.tsx.source:
// The book view: its chapters and scenes in reading order with each scene's header, the bible and
// the outline, the flags the checks have open, and export for the Owner. The list is Carrel's index
// of the book's folder in Git; Refresh reads Git again.

import type { ReactNode } from "react";
import { Form, Link, redirect, useNavigation } from "react-router";
import { Alert, Banner } from "capsomer/react/banner";
import { Button, ButtonGroup } from "capsomer/react/button";
import { Empty } from "capsomer/react/empty";
import { Field } from "capsomer/react/field";
import { Panel } from "capsomer/react/panel";
import { Row, RowList } from "capsomer/react/row-list";
import { Select } from "capsomer/react/select";
import { StatTile, StatTiles } from "capsomer/react/stat-tile";
import { Status } from "capsomer/react/status";

import { PageHead } from "~/components/page-head";

import { bookRepo, draftPaths, exportGate, listFiles, listFindings, refreshBook, requireBookProject } from "~/lib/books.server";
import { getEnv, getViewer } from "~/lib/context";
import { chapterOf, nextNumbered, readingOrder, slugify, titleFromSegment } from "~/lib/novels/layout";
import { can } from "~/lib/roles";

import type { Route } from "./+types/book";

export function meta({ loaderData: data }: Route.MetaArgs) {
  return [{ title: data ? `${data.project.name} · Carrel` : "Carrel" }];
}

const BIBLE_FOLDERS = { character: "characters", place: "places", rule: "rules" } as const;

export async function loader({ params, context }: Route.LoaderArgs) {
  const env = getEnv(context);
  const viewer = getViewer(context);
  const project = await requireBookProject(env.DB, viewer, params.project, "read");
  const [files, open, drafts] = await Promise.all([
    listFiles(env.DB, project),
    listFindings(env.DB, project, { status: "open" }),
    draftPaths(env.DB, project, viewer),
  ]);
  const flags = new Map<string, number>();
  for (const f of open) flags.set(f.path, (flags.get(f.path) ?? 0) + 1);

  const chapters: { slug: string; title: string; words: number; flags: number; scenes: { path: string; name: string; pov: string; date: string; location: string; words: number; flags: number }[] }[] = [];
  for (const file of readingOrder(files)) {
    const slug = chapterOf(file.path)!;
    let chapter = chapters.at(-1);
    if (!chapter || chapter.slug !== slug) {
      chapter = { slug, title: titleFromSegment(slug), words: 0, flags: 0, scenes: [] };
      chapters.push(chapter);
    }
    const header = file.meta.kind === "scene" ? file.meta.header : null;
    const n = flags.get(file.path) ?? 0;
    chapter.words += file.words;
    chapter.flags += n;
    chapter.scenes.push({
      path: file.path,
      name: titleFromSegment(file.path.split("/")[2]!.replace(/\.md$/, "")),
      pov: header?.pov ?? "",
      date: header?.date ?? "",
      location: header?.location ?? "",
      words: file.words,
      flags: n,
    });
  }

  const bible = files.flatMap(({ path, meta }) =>
    meta.kind === "character" || meta.kind === "place" || meta.kind === "rule"
      ? [{ path, kind: meta.kind, name: meta.entry.name, flags: flags.get(path) ?? 0 }]
      : [],
  );
  const others = files.filter((f) => f.kind === "outline" || f.kind === "note" || f.kind === "book").map((f) => ({ path: f.path, kind: f.kind }));
  const known = new Set(files.map((f) => f.path));
  const connection = bookRepo(env);
  const canPublish = can(project.role, "publish");

  return {
    project: { slug: project.slug, name: project.name, book: project.book },
    canEdit: can(project.role, "edit"),
    canPublish,
    connected: connection.repo !== null,
    connectionDetail: connection.detail,
    chapters,
    bible,
    others,
    hasBookFile: known.has("book.md"),
    words: files.filter((f) => f.kind === "scene").reduce((n, f) => n + f.words, 0),
    open: open.length,
    exportReady: canPublish ? (await exportGate(env.DB, project)).ok : false,
    // Drafts of files Git does not have yet, so a started scene is not lost from view.
    unsaved: drafts.filter((p) => !known.has(p)),
  };
}

export async function action({ params, request, context }: Route.ActionArgs) {
  const env = getEnv(context);
  const project = await requireBookProject(env.DB, getViewer(context), params.project, "read");
  const form = await request.formData();
  const intent = String(form.get("intent") ?? "");

  if (intent === "refresh") {
    const { repo, detail } = bookRepo(env);
    if (!repo) return { refreshed: null, error: detail };
    try {
      return { refreshed: await refreshBook(env.DB, repo, project), error: null };
    } catch (error) {
      return { refreshed: null, error: error instanceof Error ? error.message : String(error) };
    }
  }

  // Starting a file only opens the editor on it; nothing reaches Git until the first Save.
  if (!can(project.role, "edit")) throw new Response("Forbidden", { status: 403 });
  const name = String(form.get("name") ?? "").trim();
  const slug = slugify(name);
  if (!slug) return { refreshed: null, error: "Give it a name with at least one letter or digit." };
  const files = await listFiles(env.DB, project);

  if (intent === "new-chapter") {
    const chapters = [...new Set(files.map((f) => chapterOf(f.path)).filter((c): c is string => c !== null))];
    return redirect(`/b/${project.slug}/f/chapters/${nextNumbered(chapters, slug)}/01-${slugify(String(form.get("scene") ?? "")) || "opening"}.md`);
  }
  if (intent === "new-bible") {
    const kind = String(form.get("kind") ?? "") as keyof typeof BIBLE_FOLDERS;
    if (!Object.hasOwn(BIBLE_FOLDERS, kind)) throw new Response("Bad request", { status: 400 });
    return redirect(`/b/${project.slug}/f/bible/${BIBLE_FOLDERS[kind]}/${slug}.md?name=${encodeURIComponent(name)}`);
  }
  if (intent === "new-outline") return redirect(`/b/${project.slug}/f/outline/${slug}.md`);
  throw new Response("Bad request", { status: 400 });
}

export default function Book({ loaderData, actionData }: Route.ComponentProps) {
  const { project, canEdit, canPublish, connected, connectionDetail, chapters, bible, others, words, open, exportReady, unsaved, hasBookFile } = loaderData;
  const navigation = useNavigation();
  const refreshing = navigation.state !== "idle" && navigation.formData?.get("intent") === "refresh";
  const base = `/b/${project.slug}`;
  const file = (path: string) => `${base}/f/${path}`;
  const link = ({ href, children }: { href: string; children: ReactNode }) => <Link to={href}>{children}</Link>;

  return (
    <div className="app-page">
      <PageHead
        title={project.name}
        lead={
          <>
            <span className="cap-mono">{project.book}/</span> in the novels repository.
          </>
        }
        actions={
          <>
            {connected ? (
              <Form method="post">
                <Button type="submit" name="intent" value="refresh" pending={refreshing}>
                  {refreshing ? "Refreshing" : "Refresh from Git"}
                </Button>
              </Form>
            ) : null}
            <Link to={`${base}/authorship`} className="cap-btn" reloadDocument>
              Authorship record
            </Link>
            {canPublish ? (
              exportReady ? (
                <ButtonGroup label="Export">
                  <a className="cap-btn" href={`${base}/export/epub`}>
                    ePub
                  </a>
                  <a className="cap-btn" href={`${base}/export/docx`}>
                    Word
                  </a>
                  <a className="cap-btn" href={`${base}/export/print`} target="_blank" rel="noreferrer">
                    Print or PDF<span className="cap-sr-only"> (opens in a new tab)</span>
                  </a>
                </ButtonGroup>
              ) : (
                <Button disabledReason="Export waits until every flag is fixed or dismissed.">Export</Button>
              )
            ) : null}
          </>
        }
      />

      <StatTiles label="The book at a glance">
        <StatTile label="Words in scenes" figure={words.toLocaleString()} detail={`${chapters.length} chapter${chapters.length === 1 ? "" : "s"}`} />
        {open === 0 ? (
          <StatTile label="Open flags" tone="ok" word="Clear" figure="0" detail="Nothing holds export." />
        ) : (
          <StatTile label="Open flags" tone="warn" word="Open" figure={open} detail="They hold export until fixed or dismissed." />
        )}
      </StatTiles>

      {!connected ? (
        <Banner tone="warn" title="Git is not connected yet">
          {connectionDetail} The book shows Carrel's last index of it, and saving waits for the connection.
        </Banner>
      ) : null}

      {actionData?.error ? (
        <Alert tone="crit">{actionData.error}</Alert>
      ) : actionData?.refreshed ? (
        <Banner tone="ok">
          {actionData.refreshed.files} files in Git, {actionData.refreshed.read} read again, {actionData.refreshed.removed} gone
          {actionData.refreshed.more ? "; more on the next refresh" : ""}.
        </Banner>
      ) : null}

      {unsaved.length > 0 ? (
        <Panel title="Your drafts not yet in Git" count={unsaved.length} flush>
          <RowList label="Your drafts not yet in Git">
            {unsaved.map((p) => (
              <Row key={p} title={<span className="cap-mono">{p}</span>} href={file(p)} renderLink={link} detail="Started here; nothing is in Git until the first Save." />
            ))}
          </RowList>
        </Panel>
      ) : null}

      <div className="app-split" data-aside>
        <Panel
          title="Chapters"
          count={chapters.length}
          flush
          footer={
            canEdit ? (
              <Form method="post" className="app-inline-form">
                <input type="hidden" name="intent" value="new-chapter" />
                <Field label="New chapter">
                  <input className="cap-input" name="name" required placeholder="Chapter name" autoComplete="off" />
                </Field>
                <Field label="First scene">
                  <input className="cap-input" name="scene" placeholder="Scene name" autoComplete="off" />
                </Field>
                <Button type="submit">Start it</Button>
              </Form>
            ) : undefined
          }
        >
          {chapters.length === 0 ? (
            <Empty kind="nothing-yet" flush title="No chapters in the index yet">
              {canEdit ? "Start the first chapter below, or refresh from Git." : "Refresh from Git to read the book's folder."}
            </Empty>
          ) : (
            chapters.map((chapter) => (
              <section key={chapter.slug} className="app-chapter" aria-labelledby={`chapter-${chapter.slug}`}>
                <h3 id={`chapter-${chapter.slug}`}>
                  <Link to={`${base}/c/${chapter.slug}`}>{chapter.title}</Link>
                  <span className="cap-muted">{chapter.words.toLocaleString()} words</span>
                  {chapter.flags ? <Status tone="warn">{chapter.flags} flagged</Status> : null}
                </h3>
                <div className="cap-table-wrap" role="region" aria-labelledby={`scenes-${chapter.slug}`} tabIndex={0}>
                  <table className="cap-table">
                    <caption id={`scenes-${chapter.slug}`} className="cap-sr-only">
                      Scenes in {chapter.title}
                    </caption>
                    <thead>
                      <tr>
                        <th scope="col">Scene</th>
                        <th scope="col">Point of view</th>
                        <th scope="col" data-drop="1">
                          Date
                        </th>
                        <th scope="col" data-drop="2">
                          Location
                        </th>
                        <th scope="col" data-num>
                          Words
                        </th>
                      </tr>
                    </thead>
                    <tbody>
                      {chapter.scenes.map((s) => (
                        <tr key={s.path}>
                          <th scope="row">
                            <Link className="cap-table-open" to={file(s.path)}>
                              {s.name}
                            </Link>
                            {s.flags ? <Status tone="warn">{s.flags} flagged</Status> : null}
                          </th>
                          <td>{s.pov}</td>
                          <td data-drop="1">{s.date}</td>
                          <td data-drop="2">{s.location}</td>
                          <td data-num>{s.words.toLocaleString()}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </section>
            ))
          )}
        </Panel>

        <div className="app-stack">
          <Panel
            title="Bible"
            count={bible.length}
            footer={
              canEdit ? (
                <Form method="post" className="app-inline-form">
                  <input type="hidden" name="intent" value="new-bible" />
                  <Field label="New entry">
                    <Select
                      name="kind"
                      defaultValue="character"
                      options={[
                        { value: "character", label: "Character" },
                        { value: "place", label: "Place" },
                        { value: "rule", label: "World rule" },
                      ]}
                    />
                  </Field>
                  <Field label="Name">
                    <input className="cap-input" name="name" required placeholder="Name" autoComplete="off" />
                  </Field>
                  <Button type="submit">Start it</Button>
                </Form>
              ) : undefined
            }
          >
            {(["character", "place", "rule"] as const).map((kind) => {
              const entries = bible.filter((b) => b.kind === kind);
              const heading = kind === "character" ? "Characters" : kind === "place" ? "Places" : "World rules";
              return (
                <section key={kind} className="app-section" aria-labelledby={`bible-${kind}`}>
                  <h3 id={`bible-${kind}`}>{heading}</h3>
                  {entries.length === 0 ? (
                    <p className="cap-muted">None yet.</p>
                  ) : (
                    <ul className="app-links">
                      {entries.map((b) => (
                        <li key={b.path}>
                          <Link to={file(b.path)}>{b.name}</Link>
                          {b.flags ? <Status tone="warn">{b.flags} flagged</Status> : null}
                        </li>
                      ))}
                    </ul>
                  )}
                </section>
              );
            })}
          </Panel>

          <Panel
            title="Outline and notes"
            footer={
              canEdit ? (
                <Form method="post" className="app-inline-form">
                  <input type="hidden" name="intent" value="new-outline" />
                  <Field label="New outline file">
                    <input className="cap-input" name="name" required placeholder="Name" autoComplete="off" />
                  </Field>
                  <Button type="submit">Start it</Button>
                </Form>
              ) : undefined
            }
          >
            {others.length === 0 && (hasBookFile || !canEdit) ? (
              <p className="cap-muted">None yet.</p>
            ) : (
              <ul className="app-links">
                {others.map((o) => (
                  <li key={o.path}>
                    <Link to={file(o.path)}>{o.kind === "book" ? "Title page (book.md)" : o.path}</Link>
                  </li>
                ))}
                {!hasBookFile && canEdit ? (
                  <li>
                    <Link to={file("book.md")}>Add a title page (book.md)</Link>
                  </li>
                ) : null}
              </ul>
            )}
          </Panel>
        </div>
      </div>
    </div>
  );
}

